+    let w = judge(&p);
+    let took = t0.elapsed();
+    assert!(w.is_empty(), "a clear 40-hole program reported: {w:?}");
+    eprintln!("forty pecked radial holes: {took:?}");
+    assert!(took.as_secs_f64() < 3.0, "40 pecked holes took {took:?}");
+}
